【信心】高', '{"regime": "ranging", "score": 0.214, "details": {"adx": {"value": 11.72, "score": 0.156}, "vol_ratio": {"value": 0.958, "score": 0.472}, "deviation": {"value": 0.0053, "score": 0.133}, "atr_change": {"value": -0.204, "score": 0.161}}, "btc_price": 80935.4, "btc_change_24h": -1.13, "funding_rate": 0, "trend_direction": "down", "fear_greed": 45, "regime_label": "震荡"}', '2026-05-07 13:34:21');
